var gridEl = document.getElementById('gameGrid');
var viewList = document.getElementById('view-list');
var viewDetail = document.getElementById('view-detail');
var toastEl = document.getElementById('toast');
var toastTimer = null;

function toast(msg){
  toastEl.textContent = msg;
  toastEl.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(function(){ toastEl.classList.remove('show'); }, 2200);
}

function esc(s){
  return String(s).replace(/[&<>"']/g, function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  });
}
/* agentCode 仅允许 <b> 标签（数据受控，先全量转义再仅还原 b 标签，杜绝注入） */
function safeAgent(s){
  return esc(String(s)).replace(/&lt;(\/?)b&gt;/g, '<$1b>');
}

var filterCat = '全部';
var searchEl = null;

function cardHTML(g){
  var ph = g.thumb
    ? '<img class="row-thumb" src="' + g.thumb + '" alt="' + esc(g.name) + '" width="46" height="46" loading="lazy" decoding="async">'
    : '<div class="row-ph">游戏图</div>';
  return '<a class="row-card" href="#/game/' + encodeURIComponent(g.id) + '">' +
      ph +
      '<div class="row-info">' +
        '<h3>' + esc(g.name) + '</h3>' +
        '<p>' + esc(g.slogan) + '</p>' +
      '</div>' +
      '<span class="badge' + (g.badgeWarn?' red':'') + '">' + esc(g.badge) + '</span>' +
      '<span class="row-arrow"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 6l6 6-6 6"/></svg></span>' +
    '</a>';
}

function emptyHTML(){
  return '<p style="color:var(--tx-mute);text-align:center;padding:46px 0">没有找到匹配的传奇，换个分类或关键词试试</p>';
}

function renderCatFold(){
  var btn = document.getElementById('catFoldBtn');
  var panel = document.getElementById('catFoldPanel');
  var arrow = '<svg class="cf-arrow" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M6 9l6 6 6-6"/></svg>';
  btn.innerHTML = '<span class="cf-label">分类</span><span class="cf-cur">' + esc(filterCat) + '</span>' + arrow;
  var items = ['<button class="cat-item' + (filterCat==='全部'?' on':'') + '" data-cat="全部">全部游戏<em>' + GAMES.length + '</em></button>'];
  CATEGORIES.forEach(function(c){
    var n = GAMES.filter(function(g){ return g.category === c; }).length;
    items.push('<button class="cat-item' + (filterCat===c?' on':'') + '" data-cat="' + esc(c) + '">' + esc(c) + '<em>' + n + '</em></button>');
  });
  panel.innerHTML = items.join('');
  panel.querySelectorAll('.cat-item').forEach(function(b){
    b.addEventListener('click', function(){
      filterCat = this.dataset.cat;
      foldOpen = false;
      document.getElementById('catFold').classList.remove('open');
      btn.setAttribute('aria-expanded','false');
      renderCatFold();
      renderList();
    });
  });
}

var foldOpen = false;
document.getElementById('catFoldBtn').addEventListener('click', function(){
  foldOpen = !foldOpen;
  document.getElementById('catFold').classList.toggle('open', foldOpen);
  this.setAttribute('aria-expanded', foldOpen ? 'true' : 'false');
  if (foldOpen) {   // 展开分类浮层入栈，手机返回键可收起
    if(window.__cqUndo) window.__cqUndo.push({kind:'cat'});
    try { history.pushState({cq:1}, ''); } catch(e){}
  }
});
document.addEventListener('click', function(e){
  if(!e.target.closest('.cat-fold') && foldOpen){
    foldOpen = false;
    document.getElementById('catFold').classList.remove('open');
    document.getElementById('catFoldBtn').setAttribute('aria-expanded','false');
  }
});
// 详情页折叠分区：点击标题展开/收起
document.addEventListener('click', function(e){
  var head = e.target.closest('.sec-head');
  if(!head) return;
  var coll = head.closest('.sec-coll');
  var open = coll.classList.toggle('open');
  head.setAttribute('aria-expanded', open ? 'true' : 'false');
  if (open) {   // 展开详情分区入栈，手机返回键逐层收起
    if(window.__cqUndo) window.__cqUndo.push({kind:'sec'});
    try { history.pushState({cq:1}, ''); } catch(e){}
  }
});

function renderList(){
  if(!searchEl){ searchEl = document.getElementById('search'); searchEl.addEventListener('input', renderList); }
  var kw = (searchEl.value || '').trim().toLowerCase();
  var grid = document.getElementById('gameGrid');
  document.getElementById('zoneCount').textContent = '共 ' + GAMES.length + ' 款 · 分类筛选 / 搜索定位';

  if(filterCat === '全部' && !kw){
    // 全部：按分类分组展示
    var html = '';
    CATEGORIES.forEach(function(cat){
      var games = GAMES.filter(function(g){ return g.category === cat; });
      if(!games.length) return;
      html += '<div class="cat-head"><span>' + esc(cat) + '</span>' +
              '<em>' + games.length + ' 款</em></div>' +
              '<div class="row-grid">' + games.map(cardHTML).join('') + '</div>';
    });
    grid.innerHTML = html || emptyHTML();
  } else {
    // 筛选 / 搜索：平铺
    var list = GAMES.filter(function(g){
      var catOk = (filterCat === '全部' || g.category === filterCat);
      var kwOk = !kw || g.name.toLowerCase().indexOf(kw) > -1;
      return catOk && kwOk;
    });
    if(!list.length){ grid.innerHTML = emptyHTML(); }
    else { grid.innerHTML = '<div class="row-grid">' + list.map(cardHTML).join('') + '</div>'; }
  }
}

function renderDetail(id){
  var g = null;
  GAMES.forEach(function(x){ if(x.id === id) g = x; });
  if(!g){
    viewList.classList.add('on');
    viewDetail.classList.remove('on');
    return;
  }
  document.getElementById('dName').textContent = g.name;
  document.getElementById('dSlogan').textContent = g.slogan;
  document.getElementById('dBadges').innerHTML = '<span class="badge">' + esc(g.badge) + '</span>';
  document.getElementById('dRegister').dataset.url = g.regLink || '#';
  var payBtn = document.getElementById('dRecharge');
  if(payBtn){ payBtn.dataset.url = g.payLink || '#'; payBtn.style.display = (g.payLink && g.payLink !== '#') ? '' : 'none'; }
  document.getElementById('dAgent').innerHTML = '进服注册：' + safeAgent(g.agentCode);
  (function(){
      var ph = document.getElementById('dPoster');
      ph.style.setProperty('--poster-ratio','3/4');
      if(g.hero){
        var img = new Image();
        img.onload = function(){
          if(img.naturalWidth && img.naturalHeight)
            ph.style.setProperty('--poster-ratio',(img.naturalWidth/img.naturalHeight).toFixed(4));
        };
        img.src = g.hero;
      }
    })();
    document.getElementById('dPoster').innerHTML = g.hero
    ? '<img class="poster-img" src="' + g.hero + '" alt="' + esc(g.name) + '">'
    : '【宣传海报位】';

  var html = '';
  function secColl(title, body){
    return '<div class="sec-coll"><button class="sec-head" type="button" aria-expanded="false">' + esc(title) +
      '<svg class="sh-arrow" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M6 9l6 6 6-6"/></svg></button>' +
      '<div class="sec-body">' + body + '</div></div>';
  }
  // 分区：礼包码
  if(g.codes && g.codes.length){
    var codesBody = '<div class="codes">';
    g.codes.forEach(function(c){
      codesBody += '<div class="code-chip"><span class="code-name">' + esc(c.code) + '</span>' +
              '<span class="code-items">' + c.items.map(esc).join(' · ') + '</span></div>';
    });
    codesBody += '</div>';
    html += secColl('进服礼包码', codesBody);
  }
  // 分区：上线福利
  if(g.benefits && g.benefits.length){
    html += secColl('上线福利 / 活动说明',
      '<ul>' + g.benefits.map(function(b){ return '<li>' + esc(b) + '</li>'; }).join('') + '</ul>');
  }
  // 分区：攻略正文（含图片画廊）
  (g.sections || []).forEach(function(s){
    var body = '<ul>' + s.items.map(function(i){ return '<li>' + esc(i) + '</li>'; }).join('') + '</ul>';
    if(s.imgs && s.imgs.length){
      body += '<div class="gallery">';
      s.imgs.forEach(function(u, idx){
        var url = u, cap = '';
        if(typeof u === 'object' && u.video){
          cap = u.cap || '';
          body += '<figure class="gal-item">' +
            '<div class="gal-frame gal-video"><video controls playsinline preload="none" poster="' + (u.poster||'') + '" data-vp src="' + u.video + '"></video></div>' +
            '<figcaption class="gal-cap"><i>' + esc(s.title) + '</i><span>' + (cap || ('视频 ' + (idx+1) + ' / ' + s.imgs.length)) + '</span></figcaption>' +
            '</figure>';
          return;
        }
        if(typeof u === 'object' && u.url){ url = u.url; cap = u.cap || ''; }
        body += '<figure class="gal-item">' +
          '<div class="gal-frame"><img src="' + url + '" alt="' + esc(s.title) + '" loading="lazy"></div>' +
          '<figcaption class="gal-cap"><i>' + esc(s.title) + '</i><span>' + (cap || ('图 ' + (idx+1) + ' / ' + s.imgs.length)) + '</span></figcaption>' +
          '</figure>';
      });
      body += '</div>';
    }
    html += secColl(s.title, body);
  });
  document.getElementById('dBody').innerHTML = html;
}

function router(){
  var hash = location.hash || '#/list';
  var m = hash.match(/^#\/game\/(.+)$/);
  if(m){
    viewList.classList.remove('on');
    viewDetail.classList.add('on');
    renderDetail(decodeURIComponent(m[1]));
    window.scrollTo(0,0);
  } else {
    viewDetail.classList.remove('on');
    viewList.classList.add('on');
    renderCatFold();
    renderList();
  }
}

// 下载按钮：真实链接到位后由 data-url 直跳；当前给占位提示
document.getElementById('dRegister').addEventListener('click', function(){
  var url = this.dataset.url;
  if(url && url !== '#'){ window.open(url, '_blank', 'noopener'); }
  else { toast('占位按钮：真实链接待填充，填好后自动跳转'); }
});
// 充值按钮：复用 payLink 数据，无链接时隐藏
var dRecharge = document.getElementById('dRecharge');
if(dRecharge){
  dRecharge.addEventListener('click', function(){
    var url = this.dataset.url;
    if(url && url !== '#'){ window.open(url, '_blank', 'noopener'); }
    else { toast('该游戏暂未开放充值通道'); }
  });
}

window.addEventListener('hashchange', router);
router();

/* 内联 onclick="this.play()" 的委托替代（严格 CSP 下 inline handler 会被拦截） */
document.addEventListener('click', function (e) {
  var v = e.target.closest && e.target.closest('video[data-vp]');
  if (v) { try { v.play(); } catch (err) {} }
});
